WITH selected(name) AS (VALUES ('auth.users'),('public.agent_commission_settlements'),('public.agent_commission_unsettled_rollup'),('public.agent_commissions'),('public.agent_commissions_unsettled'),('public.agents'),('public.bbj_pools'),('public.ca_account_snapshots'),('public.ca_currency_meter'),('public.ca_detector_registry'),('public.ca_drift_incidents'),('public.ca_financial_epochs'),('public.ca_guard_def_history'),('public.ca_incident_events'),('public.ca_incident_file_failures'),('public.ca_incident_notify_ledger'),('public.ca_incident_recipients'),('public.ca_kill_switch_policy'),('public.ca_ledger_mutation_log'),('public.ca_mint_ledger'),('public.ca_mint_policy'),('public.ca_payout_freeze'),('public.ca_rakeback_baseline'),('public.chip_ledger'),('public.chip_transactions'),('public.club_members'),('public.clubs'),('public.financial_alerts'),('public.notifications'),('public.profiles'),('public.rakeback_period_payouts'),('public.rakeback_periods'),('public.spin_bonus_pools'),('public.table_seats'),('public.tables'),('public.tournaments'),('public.union_clubs'),('public.union_wallets'),('public.unions'),('public.vip_points'),('public.vip_points_ledger'),('supabase_migrations.schema_migrations')), chosen AS (SELECT name,to_regclass(name) oid FROM selected), objects AS (SELECT 'column_default'::text kind,s.name relation,a.attname::text coordinate,'pg_attrdef'::regclass classid,d.oid objid FROM chosen s JOIN pg_attribute a ON a.attrelid=s.oid JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attnum>0 AND NOT a.attisdropped UNION ALL SELECT 'constraint',s.name,c.conname,'pg_constraint'::regclass,c.oid FROM chosen s JOIN pg_constraint c ON c.conrelid=s.oid UNION ALL SELECT 'index',s.name,i.indexrelid::regclass::text,'pg_class'::regclass,i.indexrelid FROM chosen s JOIN pg_index i ON i.indrelid=s.oid UNION ALL SELECT 'policy',s.name,p.polname,'pg_policy'::regclass,p.oid FROM chosen s JOIN pg_policy p ON p.polrelid=s.oid UNION ALL SELECT 'trigger',s.name,t.tgname,'pg_trigger'::regclass,t.oid FROM chosen s JOIN pg_trigger t ON t.tgrelid=s.oid AND NOT t.tgisinternal) SELECT COALESCE(jsonb_agg(jsonb_build_object('relation',o.relation,'kind',o.kind,'coordinate',o.coordinate,'dependency_type',d.deptype,'referenced_type',i.type,'referenced_schema',i.schema,'referenced_name',i.name,'referenced_identity',i.identity) ORDER BY o.relation,o.kind,o.coordinate,i.type,i.identity),'[]'::jsonb) FROM objects o JOIN pg_depend d ON d.classid=o.classid AND d.objid=o.objid CROSS JOIN LATERAL pg_identify_object(d.refclassid,d.refobjid,d.refobjsubid) i;